from __future__ import annotations

import argparse
import hashlib
import json
import os
import shutil
import subprocess
import tempfile
import zipfile
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


SCHEMA = "release_verify_v0"


def utc_ts() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def sha256_bytes(b: bytes) -> str:
    h = hashlib.sha256(); h.update(b); return h.hexdigest()


def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def read_json_text(s: str) -> Any:
    return json.loads(s)


def main() -> int:
    ap = argparse.ArgumentParser(description="Verify Release Pack v0 (structure + hashes + app.exe --help)")
    ap.add_argument("--repo", default=".")
    ap.add_argument("--release-id", default=None)
    ap.add_argument("--release-zip", default=None)
    ap.add_argument("--release-hashes", default=None)
    args = ap.parse_args()

    repo = Path(args.repo).resolve()

    if args.release_zip:
        release_zip = Path(args.release_zip).resolve()
    elif args.release_id:
        release_zip = repo / "dist" / "releases" / f"{args.release_id}.zip"
    else:
        raise SystemExit("provide --release-id or --release-zip")

    if args.release_hashes:
        release_hashes = Path(args.release_hashes).resolve()
    elif args.release_id:
        release_hashes = repo / "dist" / "releases" / f"{args.release_id}.hashes.json"
    else:
        release_hashes = None

    required = [
        "app.exe",
        "config.example.json",
        "runbook.md",
        "evidence.md",
        "hashes.json",
    ]

    errors: list[str] = []

    if not release_zip.exists():
        errors.append(f"release zip not found: {release_zip}")
    if release_hashes and not release_hashes.exists():
        errors.append(f"release hashes not found: {release_hashes}")

    if errors:
        out = {"schema": SCHEMA, "ok": False, "exit_code": 2, "ts_utc": utc_ts(), "errors": errors}
        print(json.dumps(out, ensure_ascii=False))
        return 2

    zip_sha = sha256_file(release_zip)

    outer = None
    if release_hashes:
        outer = json.loads(release_hashes.read_text(encoding="utf-8-sig"))
        expected_zip_sha = outer.get("artifacts", {}).get("release_zip", {}).get("sha256")
        if expected_zip_sha and expected_zip_sha != zip_sha:
            errors.append("zip sha256 mismatch vs release hashes")

    # Verify zip contents and internal hashes.json
    with zipfile.ZipFile(release_zip, "r") as zf:
        names = sorted(zf.namelist())
        if sorted(required) != names:
            errors.append(f"zip content mismatch: expected {sorted(required)} got {names}")
        try:
            hashes_raw = zf.read("hashes.json").decode("utf-8")
        except Exception:
            try:
                hashes_raw = zf.read("hashes.json").decode("utf-8-sig")
            except Exception as e:
                errors.append(f"failed to read hashes.json from zip: {e}")
                hashes_raw = None

        internal_hashes = None
        if hashes_raw is not None:
            try:
                internal_hashes = read_json_text(hashes_raw)
            except Exception as e:
                errors.append(f"invalid hashes.json JSON: {e}")

        if internal_hashes:
            files_map = internal_hashes.get("files", {})
            for fname in ["app.exe", "config.example.json", "runbook.md", "evidence.md"]:
                if fname not in files_map:
                    errors.append(f"hashes.json missing entry: {fname}")
                    continue
                data = zf.read(fname)
                got = sha256_bytes(data)
                if got != files_map[fname]:
                    errors.append(f"sha256 mismatch for {fname}")

    # Verify hashes.json sha if outer available
    if outer:
        exp_hashes_sha = outer.get("artifacts", {}).get("hashes_json", {}).get("sha256")
        if exp_hashes_sha:
            # extract hashes.json from zip and hash it
            with zipfile.ZipFile(release_zip, "r") as zf:
                hdata = zf.read("hashes.json")
            got_hashes_sha = sha256_bytes(hdata)
            if got_hashes_sha != exp_hashes_sha:
                errors.append("hashes.json sha256 mismatch vs release hashes")

    # Execute app.exe --help (sandbox temp dir)
    exec_res = None
    with tempfile.TemporaryDirectory(prefix="release_verify_") as td:
        tdir = Path(td)
        with zipfile.ZipFile(release_zip, "r") as zf:
            zf.extractall(tdir)
        exe = tdir / "app.exe"
        if not exe.exists():
            errors.append("app.exe missing after extract")
        else:
            p = subprocess.run([str(exe), "--help"], cwd=str(tdir), capture_output=True, text=True)
            exec_res = {
                "rc": p.returncode,
                "stdout": (p.stdout or ""),
                "stderr": (p.stderr or ""),
            }
            if p.returncode != 0:
                errors.append("app.exe --help returned non-zero")

    ok = len(errors) == 0
    out = {
        "schema": SCHEMA,
        "ok": ok,
        "exit_code": 0 if ok else 1,
        "ts_utc": utc_ts(),
        "release_zip": str(release_zip),
        "zip_sha256": zip_sha,
        "release_hashes": str(release_hashes) if release_hashes else None,
        "errors": errors,
        "exec": exec_res,
    }
    print(json.dumps(out, ensure_ascii=False))
    return out["exit_code"]


if __name__ == "__main__":
    raise SystemExit(main())

